window.docContents[29].resolve({"/6___-Quiver-representations/6___8___-Proof-of-Gabriel___s-theorem/Example-6___8___5___-Reflection-functors-on-D4/#Chapter6___Example6___8___5":{"contents":"Example 6.8.5. Let us demonstrate by example how reflection functors work. Consider the quiver D_4 with the orientation of all arrows towards the node (which is labeled by 4). Start with the 1-dimensional representation V_{\\alpha_4} sitting at the fourth vertex. Apply to V_{\\alpha_4} the functor F_3^- F_2^- F_1^-. This yields\n\nF_1^- F_2^- F_3^- V_{\\alpha_4} = V_{\\alpha_1 + \\alpha_2 + \\alpha_3 + \\alpha_4}.\n\nNow applying F_4^-, we get\n\nF_4^- F_1^- F_2^- F_3^- V_{\\alpha_4} = V_{\\alpha_1 + \\alpha_2 + \\alpha_3 + 2\\alpha_4}.\n\nNote that this is exactly the inclusion of three lines into the plane, which is the most complicated indecomposable representation of the D_4 quiver.\n\n\n\n","context":"Introduction to Representation Theory\t6. Quiver representations\t6.8. Proof of Gabriel's theorem\tExample 6.8.5: Reflection functors on D4","header":"Example 6.8.5: Reflection functors on D4","id":"/6___-Quiver-representations/6___8___-Proof-of-Gabriel___s-theorem/Example-6___8___5___-Reflection-functors-on-D4/#Chapter6___Example6___8___5"},"/5___-Representations-of-finite-groups___-Further-results/5___19___-Schur-Weyl-duality-for-___GL_LPAR_V_RPAR____/Section-5___19___-Schur-Weyl-duality-for-GL_LPAR_V_RPAR_/#Chapter5___Introduction_5___19___heading-1":{"contents":"The Schur-Weyl duality for the Lie algebra \\mathfrak{gl}(V) implies a similar statement for the group GL(V).\n\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results\t5.19. Schur-Weyl duality for $GL(V)$\tSection 5.19: Schur-Weyl duality for GL(V)","header":"5.19. Schur-Weyl duality for  GL(V)","id":"/5___-Representations-of-finite-groups___-Further-results/5___19___-Schur-Weyl-duality-for-___GL_LPAR_V_RPAR____/Section-5___19___-Schur-Weyl-duality-for-GL_LPAR_V_RPAR_/#Chapter5___Introduction_5___19___heading-1"},"/6___-Quiver-representations/6___4___-Roots/Section-6___4-heading-and-setup/#Introduction-to-Representation-Theory--6___-Quiver-representations--6___4___-Roots--Section-6___4-heading-and-setup":{"contents":"\n\n","context":"Introduction to Representation Theory\t6. Quiver representations\t6.4. Roots","header":"Section 6.4 heading and setup","id":"/6___-Quiver-representations/6___4___-Roots/Section-6___4-heading-and-setup/#Introduction-to-Representation-Theory--6___-Quiver-representations--6___4___-Roots--Section-6___4-heading-and-setup"},"/7___-Introduction-to-categories/7___3___-Morphisms-of-functors/#chapter-07___section-7-3":{"contents":"\n\n\n\n\n\n","context":"Introduction to Representation Theory\t7. Introduction to categories","header":"7.3. Morphisms of functors","id":"/7___-Introduction-to-categories/7___3___-Morphisms-of-functors/#chapter-07___section-7-3"}});
